const request = $input.first().json;
const envelope = request.body && typeof request.body === 'object' ? request.body : request;
if (envelope.schema !== 'dominium.toa.cloud-snapshot.v1') throw new Error('Schema de snapshot inválido');
if (!envelope.feed || typeof envelope.feed !== 'object') throw new Error('Snapshot sem o campo feed');
const feed = envelope.feed;
if (!Array.isArray(feed.orders) || !Array.isArray(feed.timelineActivities)) throw new Error('Snapshot TOA sem as coleções esperadas');

const safeKey = (value) => String(value || 'sem-id').replace(/[.#$\[\]\/]/g, '_').slice(0, 700);
const hash = (value) => {
  const text = JSON.stringify(value);
  let result = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    result ^= text.charCodeAt(index);
    result = Math.imul(result, 16777619);
  }
  return (result >>> 0).toString(16);
};
const keyed = (items, keyOf) => {
  const output = {};
  const occurrences = {};
  items.forEach((item, index) => {
    const base = safeKey(keyOf(item, index));
    occurrences[base] = (occurrences[base] || 0) + 1;
    const key = occurrences[base] === 1 ? base : `${base}_${occurrences[base]}`;
    output[key] = item;
  });
  return output;
};
const stableKey = (parts, fallback) => parts.filter(Boolean).join('_') || fallback;

const orders = keyed(feed.orders, (item, index) => stableKey([
  item.activity_id || item.activityId || '',
  item.os_number || item.num_os || item.os || '',
  item.contract || '',
], `order_${index}`));
const timeline = keyed(feed.timelineActivities, (item, index) => stableKey([
  item.activity_id || item.activityId || '',
  item.type || item.activity_type || item.service || '',
  item.started_at || item.start_time || item.route_start || '',
], `timeline_${index}`));

const staticData = $getWorkflowStaticData('global');
const previousOrders = staticData.orderHashes || {};
const previousTimeline = staticData.timelineHashes || {};
const now = Date.now();
const forceFull = !staticData.lastFullAt || now - Number(staticData.lastFullAt) >= 30 * 60 * 1000;
const orderHashes = Object.fromEntries(Object.entries(orders).map(([key, value]) => [key, hash(value)]));
const timelineHashes = Object.fromEntries(Object.entries(timeline).map(([key, value]) => [key, hash(value)]));
const updates = {};
const base = 'dominium/toa/current';
updates[`${base}/schema`] = envelope.schema;
updates[`${base}/sourceKey`] = String(envelope.sourceKey || 'all');
updates[`${base}/publishedAt`] = envelope.publishedAt || new Date().toISOString();
updates[`${base}/receivedAt`] = new Date().toISOString();
updates[`${base}/trigger`] = String(envelope.trigger || '').slice(0, 120);
for (const [key, value] of Object.entries(feed)) {
  if (key !== 'orders' && key !== 'timelineActivities') updates[`${base}/feed/${safeKey(key)}`] = value ?? null;
}
for (const [key, value] of Object.entries(orders)) {
  if (forceFull || previousOrders[key] !== orderHashes[key]) updates[`${base}/feed/orders/${key}`] = value;
}
for (const key of Object.keys(previousOrders)) {
  if (!(key in orders)) updates[`${base}/feed/orders/${key}`] = null;
}
for (const [key, value] of Object.entries(timeline)) {
  if (forceFull || previousTimeline[key] !== timelineHashes[key]) updates[`${base}/feed/timelineActivities/${key}`] = value;
}
for (const key of Object.keys(previousTimeline)) {
  if (!(key in timeline)) updates[`${base}/feed/timelineActivities/${key}`] = null;
}
return [{ json: {
  updates,
  nextState: { orderHashes, timelineHashes, lastFullAt: forceFull ? now : Number(staticData.lastFullAt) },
  summary: { orders: feed.orders.length, timelineActivities: feed.timelineActivities.length, changedPaths: Object.keys(updates).length, forceFull },
} }];

const prepared = $('Preparar atualizações').first().json;
const staticData = $getWorkflowStaticData('global');
staticData.orderHashes = prepared.nextState.orderHashes;
staticData.timelineHashes = prepared.nextState.timelineHashes;
staticData.lastFullAt = prepared.nextState.lastFullAt;
return [{ json: { ok: true, provider: 'firebase-realtime-database', ...prepared.summary } }];
